import json,importlib.util
spec=importlib.util.spec_from_file_location("g","ground.py"); g=importlib.util.module_from_spec(spec); spec.loader.exec_module(g)
rows=[json.loads(l) for l in open('step3_rows.jsonl')]
L={'s':0,'p':1,'d':2,'f':3,'g':4}; cap={'s':2,'p':6,'d':10,'f':14}
def occ(Z,sub):
    n=int(sub[:-1]); l=L[sub[-1]]
    return sum(o for nn,ll,o in g.expand(Z) if nn==n and ll==l)
def walk(P=None,k=None):
    hits=0; changed=[]
    for r in rows:
        a=r['A']  # rule A argmin in EA
        o=occ(r['Z']-1,a)
        pick=a
        if a[-1] in 'df' and 2*o==cap[a[-1]]:
            EB=dict(r['EB']); pen = P if P is not None else k*abs(EB[a])
            EB[a]+=pen
            pick=min(EB,key=EB.get)
        if pick!=a: changed.append((r['el'],a,pick,r['obs']))
        hits+= (pick==r['obs'])
    return hits,changed
base=sum(r['hitA'] for r in rows)
print("baseline A hits:",base,"/",len(rows))
for P in (0.126,0.15,0.17,0.20,0.214):
    h,c=walk(P=P); print(f"P={P}: {h}/106  changed={[(e,a,'->',p) for e,a,p,o in c]}")
for k in (0.44,0.48,0.52):
    h,c=walk(k=k); print(f"k={k}: {h}/106  changed={[(e,a,'->',p) for e,a,p,o in c]}")
# edges: just outside the corridor
for P in (0.12,0.22):
    h,c=walk(P=P); print(f"P={P} (outside): {h}/106 changed {len(c)}")
